#include <bits/stdc++.h> 

using namespace std;

#define pb push_back
#define mp make_pair
#define fs first
#define sc second
#define sz(x) (int) ((x).size()) 
#define forn(i, n) for (int i = 0; (i) < (n); ++i)
#define all(c) (c).begin(), (c).end()

#ifdef LOCAL
	#define eprintf(...) fprintf(stderr, __VA_ARGS__)
#else
	#define eprintf(...) static_cast<void>(0)
#endif

#ifdef _WIN32
	#define I64 "%I64d"
#else
	#define I64 "%lld"
#endif

typedef long long ll;
typedef vector<int> vi;
typedef pair<int, int> pii;

const int MAX_N = 10, MOD = 1e9 + 7;

int matrix[MAX_N][MAX_N];

inline int add_mod(int a, int b) {
	a += b;
	return a >= MOD ? a - MOD : a;
}

inline int sub_mod(int a, int b) {
	a -= b;
	return a < 0 ? a + MOD : a;
}

inline int mul_mod(int a, int b) {
	return (a * 1ll * b) % MOD;
}

inline int pow_mod(int a, int n) {
	if (n == 0) return 1;
	int half = pow_mod(a, n / 2);
	half = mul_mod(half, half);
	return (n & 1) ? mul_mod(half, a) : half;
}

inline int inv_mod(int a) {
	return pow_mod(a, MOD - 2);
}

inline int div_mod(int a, int b) {
	return mul_mod(a, inv_mod(b));
}

int main() {
#ifdef LOCAL
	freopen("input.in", "r", stdin);
	freopen("output.out", "w", stdout);
#endif

	int n;
	scanf("%d", &n);
	forn(i, n)
		forn(j, n) {
			scanf("%d", &matrix[i][j]);
			matrix[i][j] = div_mod(matrix[i][j], 100);
		}
	vector<pair<vi, int>> sets, newSets;
	vi baseSet;
	baseSet.push_back(0);
	sets.pb(mp(baseSet, 1));
	forn(g, n) {
		newSets.clear();
		forn(mask, (1 << n)) {
			int val = 1;
			forn(j, n)
				if (mask & (1 << j))
					val = mul_mod(val, matrix[j][g]);
				else
					val = mul_mod(val, sub_mod(1, matrix[j][g]));
			for (auto& p : sets) {
				vi currentSet;
				for (int m2 : p.fs) {
					int possible = (~m2) & mask;
					while (possible) {
						int pos = possible & (-possible);
						currentSet.pb(m2 | pos);
						possible ^= pos;
					}
				}
				if (sz(currentSet) == 0) continue;
				sort(all(currentSet));
				currentSet.erase(unique(all(currentSet)), currentSet.end());
				newSets.pb(mp(currentSet, mul_mod(p.sc, val)));
			}
		}
		sort(all(newSets));
		sets.clear();
		int i = 0;
		while (i < (int)newSets.size()) {
			int j = i;
			int sumVal = 0;
			while (j < (int)newSets.size() && newSets[j].fs == newSets[i].fs)
				sumVal = add_mod(sumVal, newSets[j].sc), j++;
			sets.pb(mp(newSets[i].fs, sumVal));
			i = j;
		}
	}
	int result = 0;
	for (auto& p : sets)
		result = add_mod(result, p.sc);
	printf("%d\n", result);
	return 0;
}
